<section class="mx-auto max-w-xl space-y-5"><header><p class="text-sm font-semibold uppercase tracking-widest text-primary">Security</p><h1 class="mt-2 text-3xl font-bold"><?= e($title) ?></h1><p class="mt-2 text-zinc-600 dark:text-zinc-300"><?php if($mode==='change'): ?>Update the password for your account.<?php else: ?>Set a new password for <?= e($person['full_name']??$person['username']??'this user') ?>. Their existing sessions will be signed out.<?php endif; ?></p></header>
    <?php if($error): ?><p role="alert" class="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800 dark:border-red-900 dark:bg-red-950 dark:text-red-200"><?= e($error) ?></p><?php endif; ?>
    <?php $flash=$_SESSION['user_flash']??null;unset($_SESSION['user_flash']);if(is_array($flash)): ?><p role="status" class="rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-800 dark:border-green-900 dark:bg-green-950 dark:text-green-200"><?= e($flash['message']??'') ?></p><?php endif; ?>
    <form method="post" action="<?= $mode==='change'?'/account/security':'/users/'.(int)$person['id'].'/reset-password' ?>" class="space-y-4 rounded-xl bg-white p-5 shadow-sm ring-1 ring-zinc-200 dark:bg-dark-card dark:ring-zinc-800"><input type="hidden" name="_csrf_token" value="<?= e($csrfToken) ?>">
        <?php if($mode==='change'): ?><div><label for="current_password" class="mb-1.5 block text-sm font-medium">Current password</label><input id="current_password" name="current_password" type="password" autocomplete="current-password" required class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"></div><?php endif; ?>
        <div><label for="new_password" class="mb-1.5 block text-sm font-medium">New password</label><input id="new_password" name="new_password" type="password" minlength="12" autocomplete="new-password" required class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"><p class="mt-1 text-xs text-zinc-500">Use at least 12 characters.</p></div>
        <div><label for="confirm_password" class="mb-1.5 block text-sm font-medium">Confirm new password</label><input id="confirm_password" name="confirm_password" type="password" minlength="12" autocomplete="new-password" required class="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2.5 dark:border-zinc-700 dark:bg-zinc-900"></div>
        <div class="flex justify-end gap-3 pt-2"><a href="<?= $mode==='change'?'/dashboard':'/users' ?>" class="rounded-lg border border-zinc-300 px-4 py-2.5 text-sm font-semibold dark:border-zinc-700">Cancel</a><button class="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary-hover" type="submit"><?= $mode==='change'?'Change password':'Reset password' ?></button></div>
    </form>
</section>
